//*****************************************************************************
// Init-time table builders
//*****************************************************************************
static uint32_t ScaleRgb(uint32_t rgb, uint16_t m)      // m is Q8
{
    uint32_t r = (((rgb >> 16) & 0xFFUL) * m) >> 8;
    uint32_t g = (((rgb >>  8) & 0xFFUL) * m) >> 8;
    uint32_t b = (( rgb        & 0xFFUL) * m) >> 8;
    return (r << 16) | (g << 8) | b;
}


// All sprite colours share one id table, de-duplicated by RGB value.
static uint16_t s_nCol;

static uint16_t ColorId(uint32_t rgb)
{
    uint16_t i;

    for(i = 0; i < s_nCol; i++)
        if(rc_sprRgb[i] == rgb) return (uint16_t)(ID_SPR + i);
    if(s_nCol < SPR_COLORS)
    {
        rc_sprRgb[s_nCol] = rgb;
        return (uint16_t)(ID_SPR + s_nCol++);
    }
    return (uint16_t)(ID_SPR + SPR_COLORS - 1);
}


static void SetPal(uint16_t type, const uint32_t *pal)
{
    uint16_t i;

    for(i = 0; i < PAL_N; i++) rc_palId[type][i] = ColorId(pal[i]);
}


// Switch the wall theme: recolours stone, mortar, accents, floor and ceiling.
void rc_ApplyTheme(uint16_t t)
{
    const Theme *th;
    uint16_t     sh;

#if !RC_WALL_THEMES
    t = TH_BASEMENT;
#endif
    th = &rc_kTheme[t];
    rc_theme = t;
    for(sh = 0; sh < 4; sh++)
    {
        rc_wallCol[1][sh][0] = ScaleRgb(th->base, rc_kShadeMul[sh]);
        rc_wallCol[1][sh][1] = ScaleRgb(rc_wallCol[1][sh][0], 200);
        rc_wallCol[2][sh][0] = ScaleRgb(th->base, (uint16_t)((rc_kShadeMul[sh] * 5u) >> 2));
        rc_wallCol[2][sh][1] = ScaleRgb(rc_wallCol[2][sh][0], 200);
        rc_themeCol[0][sh][0] = ScaleRgb(th->mortar, rc_kShadeMul[sh]);
        rc_themeCol[0][sh][1] = ScaleRgb(rc_themeCol[0][sh][0], 200);
        rc_themeCol[1][sh][0] = ScaleRgb(th->accent, rc_kShadeMul[sh]);
        rc_themeCol[1][sh][1] = ScaleRgb(rc_themeCol[1][sh][0], 200);
        if(sh < 2u)
        {
            rc_bannerCol[sh * 2u]      = ScaleRgb(rc_kBannerRgb[t], rc_kShadeMul[sh]);
            rc_bannerCol[sh * 2u + 1u] = ScaleRgb(rc_bannerCol[sh * 2u], 200);
        }
    }
    rc_colFloor = th->floor;
    rc_colCeil  = th->ceil;
    rc_invalidate = true;
    rc_viewDirty  = 2;
}


uint16_t rc_ThemeOfMini(uint16_t type)
{
    switch(type)
    {
        case ET_SLIMEKING: return TH_SLIME;
        case ET_GOLEM:     return TH_GOLEM;
        case ET_VAMPIRE:   return TH_VAMPIRE;
        case ET_EYEKING:   return TH_EYE;
        case ET_LICH:      return TH_LICH;
        case ET_DRAGON:    return TH_DRAGON;
        default:           return TH_BASEMENT;
    }
}


void rc_BuildTables(void)
{
    uint16_t i, sh;
    float    s;

    if(rc_tablesReady) return;

    for(i = 0; i <= 256; i++)
    {
        s = sinf((float)i * (6.2831853f / RC_ANGLES));
        rc_qsin[i] = (int16_t)(s * 16384.0f + 0.5f);
    }

    for(i = 1; i < TILE_KINDS; i++)
        for(sh = 0; sh < 4; sh++)
        {
            rc_wallCol[i][sh][0] = ScaleRgb(rc_kWallBase[i], rc_kShadeMul[sh]);
            rc_wallCol[i][sh][1] = ScaleRgb(rc_wallCol[i][sh][0], 200);
        }

    s_nCol = 0;
    for(i = 0; i < PT_COUNT; i++) SetPal(i, rc_kPal[i]);
    rc_ApplyTheme(TH_WARRENS);

    rc_tablesReady = true;
}


//*****************************************************************************
// Rooms
//*****************************************************************************
uint16_t rc_RoomAt(int32_t x, int32_t y)
{
    uint16_t tx = (uint16_t)(x >> 10), ty = (uint16_t)(y >> 10), r;

    for(r = 0; r < RM_COUNT; r++)
    {
        const RoomDef *d = &rc_kRoom[r];
        if(tx >= d->x0 && tx <= d->x1 && ty >= d->y0 && ty <= d->y1) return r;
    }
    return RM_NONE;
}


static uint16_t MarkerRoom(char ch)
{
    static const uint16_t k[7] = { RM_S, RM_SW, RM_NW, RM_N, RM_NE, RM_SE, RM_DEN };
    return k[ch - 'a'];
}


// Floor decorations. Each kind: shape, palette, flicker palette (0 = none), scale.
enum { DK_BARREL, DK_BARREL_G, DK_CANDLE, DK_CRYSTAL, DK_BONES, DK_SLIME, DK_RUNE, DK_CRATES,
       DK_COFFIN, DK_ANVIL, DK_BRAZIER, DK_HOARD, DK_SHELF, DK_CAGE, DK_STATUE };
static const uint16_t kDecor[][4] =
{
    { SH_BARREL,   PT_BARREL,       0,              10 },   // DK_BARREL
    { SH_BARREL,   PT_BARREL_G,     0,              10 },   // DK_BARREL_G (slimy)
    { SH_CANDLE,   PT_CANDLE,       PT_CANDLE_LIT,  13 },   // DK_CANDLE (candelabra)
    { SH_CRYSTAL,  PT_CRYSTAL,      0,              11 },   // DK_CRYSTAL
    { SH_BONES,    PT_BONES,        0,               6 },   // DK_BONES (walk over)
    { SH_PUDDLE,   PT_PUDDLE_SLIME, 0,              20 },   // DK_SLIME (walk over)
    { SH_PUDDLE,   PT_RUNE,         PT_RUNE_LIT,    30 },   // DK_RUNE  (walk over, pulses)
    { SH_CRATES,   PT_CRATES,       0,              12 },
    { SH_COFFIN,   PT_COFFIN,       0,              13 },
    { SH_ANVIL,    PT_ANVIL,        0,              10 },
    { SH_BRAZIER,  PT_BRAZIER,      PT_BRAZIER_LIT, 12 },
    { SH_HOARD,    PT_HOARD,        0,              12 },
    { SH_SHELF,    PT_SHELF,        0,              15 },
    { SH_CAGED,    PT_CAGED,        0,              14 },   // DK_CAGE (an old prisoner)
    { SH_MERCHANT, PT_STATUE,       0,              16 },   // DK_STATUE (Wason in bronze)
};

// What each room's 'o' (two kinds, alternating across the room) and '%' turn into.
#define KD(a, b, f)   ((a) | ((b) << 4) | ((f) << 8))
static const uint16_t kRoomDecor[RM_COUNT] =
{
    KD(DK_BARREL,   DK_CRATES,   DK_BONES),     // RM_S       Goblin Warrens
    KD(DK_CANDLE,   DK_COFFIN,   DK_BONES),     // RM_SW      Bone Crypt
    KD(DK_BARREL,   DK_CRATES,   DK_BONES),     // RM_WC
    KD(DK_BARREL_G, DK_BARREL_G, DK_SLIME),     // RM_NW      Slime Sewers
    KD(DK_CANDLE,   DK_CANDLE,   DK_BONES),     // RM_N       Haunted Chapel
    KD(DK_ANVIL,    DK_BRAZIER,  DK_BONES),     // RM_NE      Elemental Forge
    KD(DK_BARREL,   DK_CRATES,   DK_BONES),     // RM_EC
    KD(DK_CRYSTAL,  DK_CRYSTAL,  DK_RUNE),      // RM_SE      Arcane Observatory
    KD(DK_HOARD,    DK_BRAZIER,  DK_BONES),     // RM_DEN
    KD(DK_BARREL_G, DK_BARREL_G, DK_SLIME),     // RM_VAULT
    KD(DK_CANDLE,   DK_CANDLE,   DK_RUNE),      // RM_SHRINE
    KD(DK_CRYSTAL,  DK_CRYSTAL,  DK_RUNE),      // RM_LAB
    KD(DK_BARREL,   DK_CRATES,   DK_BONES),     // RM_MAZE
    KD(DK_HOARD,    DK_CRATES,   DK_BONES),     // RM_TREASURY (the bones: unlucky thieves)
    KD(DK_SHELF,    DK_SHELF,    DK_RUNE),      // RM_STUDY
    KD(DK_CAGE,     DK_COFFIN,   DK_BONES),     // RM_OSSUARY
    KD(DK_CRATES,   DK_CRATES,   DK_BONES),     // RM_CLOSET
};

Decor    rc_decor[RC_MAX_DECOR];
uint16_t rc_nDecor;

// Map letter ch at (x, y): 'o' blocking prop, '%' floor clutter, '*' rune circle, 'w' statue.
static void AddDecor(uint16_t x, uint16_t y, char ch)
{
    Decor   *d;
    uint16_t r = rc_RoomAt(TILE_C(x), TILE_C(y)), k;

    if(rc_nDecor >= RC_MAX_DECOR) return;
    if(r >= RM_COUNT) r = RM_S;
    k = kRoomDecor[r];
    k = (ch == '*') ? DK_RUNE : (ch == 'w') ? DK_STATUE : (ch == '%') ? (k >> 8) :
        (((x ^ y) & 2u) ? ((k >> 4) & 15u) : (k & 15u));
    d = &rc_decor[rc_nDecor++];
    d->tx = x;  d->ty = y;
    d->shape = kDecor[k][0];  d->pal = kDecor[k][1];  d->pal2 = kDecor[k][2];  d->scale = kDecor[k][3];
}


int16_t rc_AddProp(uint16_t kind, uint16_t sub, int32_t x, int32_t y)
{
    Prop *p;

    if(rc_nProp >= RC_MAX_PROPS) return -1;
    p = &rc_prop[rc_nProp];
    p->x = x;  p->y = y;
    p->kind = kind;  p->sub = sub;
    p->used = 0;  p->alive = 1;
    p->room = rc_RoomAt(x, y);
    return (int16_t)rc_nProp++;
}


void rc_SetTiles(char ch, uint16_t tile)
{
    uint16_t x, y;

    for(y = 0; y < RC_MAP_H; y++)
        for(x = 0; x < RC_MAP_W; x++)
            if(rc_MapCh(x, y) == ch) rc_tile[(y << RC_MAP_SHIFT) + x] = tile;
    rc_flowTx = -1;                     // re-path
    rc_viewDirty = 2;
}


// A random chest type, equal chance: regular, Mimic, cursed (rc.md 4.5).
static uint16_t RandomChest(void)
{
    return RAND(3);                     // CH_REGULAR, CH_MIMIC, CH_CURSED
}


//*****************************************************************************
// Map loading: tiles, door centres, spawn markers and every prop of the run.
//*****************************************************************************
void rc_LoadMap(void)
{
    uint16_t x, y, t, k, keyN = 0;
    int32_t  sx[RC_NUM_DOORS + 1], sy[RC_NUM_DOORS + 1];
    uint16_t cnt[RC_NUM_DOORS + 1];
    int32_t  nookX[2][3], nookY[2][3];
    uint16_t nookN[2] = { 0, 0 };
    int16_t  closet[3];
    uint16_t nCloset = 0;

    rc_spCount = 0;
    rc_nProp   = 0;
    rc_nDecor  = 0;
    for(k = 0; k <= RC_NUM_DOORS; k++) { sx[k] = 0; sy[k] = 0; cnt[k] = 0; }

    for(y = 0; y < RC_MAP_H; y++)
        for(x = 0; x < RC_MAP_W; x++)
        {
            char    ch = rc_MapCh(x, y);
            int32_t cx = TILE_C(x), cy = TILE_C(y);

            t = 0;
            if(ch >= 'a' && ch <= 'g')
            {
                if(rc_spCount < RC_MAX_SPAWNS)
                {
                    rc_spX[rc_spCount]    = cx;
                    rc_spY[rc_spCount]    = cy;
                    rc_spRoom[rc_spCount] = MarkerRoom(ch);
                    rc_spCount++;
                }
            }
            else if(ch >= '1' && ch <= '8')
            {
                k = (uint16_t)(ch - '0');
                t = TILE_DOOR;
                sx[k] += cx;  sy[k] += cy;  cnt[k]++;
            }
            else switch(ch)
            {
                case '#': case 's': case 'x': case 'M': t = TILE_WALL_STONE; break;
                case 'P': t = 2; break;
                case 'B': t = 3; break;
                case 'D': t = TILE_METAL_DOOR; break;
                case '@': rc_px = cx; rc_py = cy; break;
                case 'o': case 'w': t = TILE_BLOCK; AddDecor(x, y, ch); break;   // solid decoration
                case '%': case '*': AddDecor(x, y, ch); break;                    // floor clutter, rune circle
                case 'T': (void)rc_AddProp(PR_CHEST, CH_GOOD, cx, cy); break;    // Goblin Treasury
                case 'W': t = TILE_BLOCK; (void)rc_AddProp(PR_LECTERN, 0, cx, cy); break;
                case 'J': t = TILE_BLOCK; (void)rc_AddProp(PR_PRISONER, 0, cx, cy); break;
                case 'Q':                                                         // Mimic Closet
                    if(nCloset < 3u) closet[nCloset++] = rc_AddProp(PR_CHEST, CH_MIMIC, cx, cy);
                    break;
                case 'K': (void)rc_AddProp(PR_KEY, keyN++, cx, cy); break;
                case 'C':
                {
                    int16_t p = rc_AddProp(PR_CHEST, RandomChest(), cx, cy);
                    if(p >= 0)                  // a nook belongs to the chamber next to it
                        rc_prop[p].room = rc_RoomAt(cx, (y < RC_MAP_H / 2u) ? cy + 1024L : cy - 1024L);
                    break;
                }
                case 'v':
                    k = (x < RC_MAP_W / 2u) ? 0u : 1u;
                    if(nookN[k] < 3u) { nookX[k][nookN[k]] = cx; nookY[k][nookN[k]] = cy; nookN[k]++; }
                    break;
                case 'V': (void)rc_AddProp(PR_CHEST, CH_REGULAR, cx, cy); break;   // Slime Vault: guaranteed treasure
                case 'A': (void)rc_AddProp(PR_ALTAR_SHRINE, 0, cx, cy); break;
                case 'L': (void)rc_AddProp(PR_ALTAR_LAB, 0, cx, cy); break;
                default: break;
            }
            rc_tile[(y << RC_MAP_SHIFT) + x] = t;
        }

    for(k = 1; k <= RC_NUM_DOORS; k++)
        if(cnt[k])
        {
            rc_doorCx[k] = sx[k] / (int32_t)cnt[k];
            rc_doorCy[k] = sy[k] / (int32_t)cnt[k];
        }

    // Mimic Closet: one of its three chests is a good one, the other two bite.
    if(nCloset == 3u && closet[k = RAND(3)] >= 0) rc_prop[closet[k]].sub = CH_GOOD;

    // Corridor nooks: a vendor and a chest in two of the three, decoration in the third.
    for(k = 0; k < 2u; k++)
    {
        uint16_t v = RAND(3), c = (uint16_t)((v + 1u + RAND(2)) % 3u), d = (uint16_t)(3u - v - c), r;

        if(nookN[k] < 3u) continue;
        r = (k == 0u) ? RM_WC : RM_EC;
        rc_prop[rc_AddProp(PR_VENDOR, 0, nookX[k][v], nookY[k][v])].room = r;
        rc_prop[rc_AddProp(PR_CHEST, RandomChest(), nookX[k][c], nookY[k][c])].room = r;
        rc_tile[((uint16_t)(nookY[k][d] >> 10) << RC_MAP_SHIFT) + (uint16_t)(nookX[k][d] >> 10)] = 2;  // torch / banner pillar
    }
}


//*****************************************************************************
// The Goblin Maze (rc.md 4.10): a recursive backtracker over 7 x 7 cells inside
// the reserved 15 x 15 block, made once per run from the run seed. Entrance at
// the bottom left (the S chamber's secret door), exit on the right (one-way door
// to the east corridor), the good chest in the middle.
//*****************************************************************************
static uint16_t s_mz;

static uint16_t MazeRand(uint16_t n)
{
    s_mz = (uint16_t)(s_mz * 25173u + 13849u);
    return (uint16_t)((s_mz >> 7) % n);
}


static void MazeOpen(uint16_t lx, uint16_t ly)
{
    rc_tile[((uint16_t)(MAZE_Y0 + ly) << RC_MAP_SHIFT) + MAZE_X0 + lx] = 0;
}


void rc_BuildMaze(void)
{
    uint16_t stack[49], sp = 0, seen[7], i, cell, cx, cy, n, cand[4], k;

    s_mz = rc_seed | 1u;
    for(i = 0; i < 7u; i++) seen[i] = 0;

    // every cell of the block is wall until carved
    for(cy = 0; cy < MAZE_N; cy++)
        for(cx = 0; cx < MAZE_N; cx++)
            rc_tile[((uint16_t)(MAZE_Y0 + cy) << RC_MAP_SHIFT) + MAZE_X0 + cx] = TILE_WALL_STONE;

    stack[sp++] = 6u * 7u + 0u;                 // start at the entrance cell (bottom left)
    seen[6] |= 1u;
    MazeOpen(1, 13);

    while(sp)
    {
        cell = stack[sp - 1u];
        cx = cell % 7u;
        cy = cell / 7u;
        n = 0;
        if(cx > 0u && !(seen[cy] & (1u << (cx - 1u)))) cand[n++] = 0;
        if(cx < 6u && !(seen[cy] & (1u << (cx + 1u)))) cand[n++] = 1;
        if(cy > 0u && !(seen[cy - 1u] & (1u << cx)))   cand[n++] = 2;
        if(cy < 6u && !(seen[cy + 1u] & (1u << cx)))   cand[n++] = 3;
        if(n == 0u) { sp--; continue; }

        k = cand[MazeRand(n)];
        {
            uint16_t nx = (k == 0u) ? cx - 1u : (k == 1u) ? cx + 1u : cx;
            uint16_t ny = (k == 2u) ? cy - 1u : (k == 3u) ? cy + 1u : cy;

            MazeOpen((uint16_t)(cx + nx + 1u), (uint16_t)(cy + ny + 1u));   // the wall between
            MazeOpen((uint16_t)(nx * 2u + 1u), (uint16_t)(ny * 2u + 1u));
            seen[ny] |= (uint16_t)(1u << nx);
            stack[sp++] = (uint16_t)(ny * 7u + nx);
        }
    }

    MazeOpen(1, 14);                            // entrance: under the S chamber's secret door
    MazeOpen(14, 1);                            // exit: to the one-way door on the east corridor
    (void)rc_AddProp(PR_CHEST, CH_GOOD, TILE_C(MAZE_X0 + 7), TILE_C(MAZE_Y0 + 7));
}




//*****************************************************************************
// Render ray (one per screen column). (rdx, rdy) = dir + plane * x is NOT normalised: that is
// what makes the DDA's distance come out perpendicular to the view (no fisheye, no cosine
// table). Returns that distance in Q8 tiles, the tile and face hit, and the exact point on the
// face: *u = Q10 world coordinate along the face (low 15 bits), *v = the wall's tile row /
// column. Taking u from the DDA itself keeps brick seams and door art from swimming while
// turning (it used to be recomputed from a rounded distance with table trig).
//*****************************************************************************
#pragma CODE_SECTION(rc_CastCol, ".TI.ramfunc")          // per column: runs from RAM
uint16_t rc_CastCol(float rdx, float rdy, uint16_t *tile, uint16_t *side, uint16_t *u, uint16_t *v)
{
    float    posX = (float)rc_px * (1.0f / 1024.0f), posY = (float)rc_py * (1.0f / 1024.0f);
    int16_t  mx = (int16_t)(rc_px >> 10), my = (int16_t)(rc_py >> 10), stepX, stepY;
    float    dX = (rdx == 0.0f) ? 1.0e6f : fabsf(1.0f / rdx);
    float    dY = (rdy == 0.0f) ? 1.0e6f : fabsf(1.0f / rdy);
    float    sideX, sideY, dist = 0.0f, hit;
    uint16_t t = 1, sd = 0, i;

    if(rdx < 0.0f) { stepX = -1; sideX = (posX - (float)mx) * dX; }
    else           { stepX =  1; sideX = ((float)mx + 1.0f - posX) * dX; }
    if(rdy < 0.0f) { stepY = -1; sideY = (posY - (float)my) * dY; }
    else           { stepY =  1; sideY = ((float)my + 1.0f - posY) * dY; }

    for(i = 0; i < RC_MAX_STEPS; i++)
    {
        if(sideX < sideY) { dist = sideX; sideX += dX; mx += stepX; sd = 0; }
        else              { dist = sideY; sideY += dY; my += stepY; sd = 1; }

        if((uint16_t)mx >= RC_MAP_W || (uint16_t)my >= RC_MAP_H) { t = 1; break; }
        t = rc_tile[((uint16_t)my << RC_MAP_SHIFT) + (uint16_t)mx];
        if(t && t != TILE_BLOCK) break;             // rays pass decorations (they are sprites)
    }

    rc_rayCx = mx;
    rc_rayCy = my;
    *tile = (t == 0 || t >= TILE_KINDS) ? 1u : t;
    *side = sd;
    hit = (sd == 0u) ? (posY + dist * rdy) : (posX + dist * rdx);  // where on the face, in tiles
    *u = (uint16_t)((int32_t)(hit * 1024.0f)) & 0x7FFFu;
    *v = (uint16_t)((sd == 0u) ? mx : my) & 63u;
    dist *= 256.0f;
    return (dist > 65535.0f) ? 65535u : (uint16_t)dist;
}
